  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, which shares the dimethoxytetrahydroisoquinoline core and basic amine motif with the query, has an absolute oral bioavailability of approximately 49% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Noscapine, a dimethoxy-substituted isoquinolinone alkaloid structurally related to the query, has an absolute oral bioavailability of about 30% (range 16–58%) in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, which contains a veratryl (3,4-dimethoxyphenyl) group and a basic amine, has an oral bioavailability of 32 ± 7% in normal subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Verapamil, a dimethoxyphenyl-containing basic drug, has an absolute oral bioavailability of 34% in humans under normal conditions, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C67"],
      "claim": "Sulpiride, a methoxyarene benzamide with a basic amine, has an oral bioavailability of 35% in humans, supporting F ≥ 20% despite qualitative descriptions of incomplete absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Levosulpiride, the enantiomer of sulpiride, has an absolute oral bioavailability of 23.4% in healthy volunteers, still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The most transferable analogues—valbenazine, noscapine, encainide, verapamil, and the sulpiride/levosulpiride pair—all share the query's dimethoxyarene and basic amine pharmacophore and report human oral bioavailability values at or above 20% (approximately 23–49%). No transferable experimental evidence supports F below 20% under normal conditions. The prediction is therefore high (F ≥ 20%), with moderate confidence due to the absence of a direct measurement on the query and the borderline values of some analogues.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule itself.",
    "Several analogues have wide interindividual ranges that dip below 20% (e.g., noscapine 16%, encainide 7%), creating uncertainty around the exact margin above threshold.",
    "The query's fused lactam/benzazepine system is not exactly matched by any single analogue; valbenazine is closest but still differs in the side-chain ester."
  ],
  "new_evidence_assessment": [
